#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gesummv.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    {
      x[i] = (DATA_TYPE)( i % n) / n;
      for (j = 0; j < n; j++) {
	A[i][j] = (DATA_TYPE) ((i*j+1) % n) / n;
	B[i][j] = (DATA_TYPE) ((i*j+2) % n) / n;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i;

#pragma scop
  /* Parallelize the outer loop over rows. Each iteration is
   * independent (writes to distinct tmp[i] and y[i]), so this is
   * safe. If OpenMP is not enabled at compile time, this pragma
   * is ignored and the code runs sequentially. */
#pragma omp parallel for schedule(static)
  for (i = 0; i < _PB_N; i++)
    {
      /* Accumulate the two dot products for row i entirely in
       * registers to reduce memory traffic.
       *
       * Original code:
       *   tmp[i] = 0; y[i] = 0;
       *   for (j) {
       *     tmp[i] = A[i][j]*x[j] + tmp[i];
       *     y[i]   = B[i][j]*x[j] + y[i];
       *   }
       *   y[i] = alpha * tmp[i] + beta * y[i];
       *
       * This transformation keeps the same recurrence for the sums
       * (only the storage location changes from tmp[i]/y[i] in memory
       * to sumA/sumB in registers), so the arithmetic sequence is
       * preserved for each i. */
      DATA_TYPE sumA = SCALAR_VAL(0.0);
      DATA_TYPE sumB = SCALAR_VAL(0.0);

      /* Local row pointers with 'restrict' to help the compiler's
       * alias analysis and enable aggressive vectorization. */
      DATA_TYPE const * restrict Ai = A[i];
      DATA_TYPE const * restrict Bi = B[i];
      DATA_TYPE const * restrict x_local = x;

      int j;

      /* Vectorizable inner loop: two dot products sharing the same
       * x[j].  The GCC 'ivdep' pragma tells the compiler to ignore
       * any spurious assumed loop-carried dependencies and to
       * vectorize if profitable. */
#pragma GCC ivdep
      for (j = 0; j < _PB_N; j++)
	{
	  DATA_TYPE xj = x_local[j];
	  sumA += Ai[j] * xj;
	  sumB += Bi[j] * xj;
	}

      /* Store final results for this row.  This exactly matches the
       * mathematical result of the original code, but with only a
       * single write to tmp[i] and y[i] instead of one write per
       * inner-loop iteration. */
      tmp[i] = sumA;
      y[i]   = alpha * sumA + beta * sumB;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
