/* Small helper macro to express alignment assumptions in a
 * portable way. On GCC/Clang this maps to a builtin that
 * helps auto-vectorization; on other compilers it is a no-op.
 */
#ifndef ASSUME_ALIGNED
#  if defined(__GNUC__) || defined(__clang__)
#    define ASSUME_ALIGNED(ptr, alignment) \
        __builtin_assume_aligned((ptr), (alignment))
#  else
#    define ASSUME_ALIGNED(ptr, alignment) (ptr)
#  endif
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    {
      /* Initialize x[i] once and reuse the value in the inner loop. */
      DATA_TYPE xi = (DATA_TYPE)(i % n) / n;
      x[i] = xi;
      for (j = 0; j < n; j++) {
	A[i][j] = (DATA_TYPE) ((i*j+1) % n) / n;
	B[i][j] = (DATA_TYPE) ((i*j+2) % n) / n;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Keep per-row dot products (for A*x and B*x) in scalar accumulators
     held in registers and write them to memory only once per row.
   - Use restrict-qualified local pointers and alignment hints to help
     the compiler generate efficient vectorized code.
   - Parallelize the outer loop over i with OpenMP; each iteration
     writes to distinct tmp[i] and y[i], so there are no data races.
   - Use #pragma omp simd on the inner loop to encourage SIMD
     vectorization with reduction on the accumulators.

   These transformations preserve the mathematical computation:
     tmp[i] = sum_j A[i][j] * x[j]
     y[i]   = alpha * tmp[i] + beta * sum_j B[i][j] * x[j]
*/
static
void kernel_gesummv [[gnu::flatten, gnu::noinline]] (int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

  /* PolyBench defines _PB_N as the effective problem size; it matches n. */
  const int N_ = _PB_N;
  (void)n; /* n is equal to N_, silence potential unused-parameter warnings. */

  /* Local, restrict-qualified views of the arrays with assumed alignment.
   * This does not change the external function interface, but gives the
   * compiler stronger aliasing and alignment information to optimize
   * the inner loops more aggressively.
   */
  DATA_TYPE (* restrict A_)[N_] =
    (DATA_TYPE (*)[N_])ASSUME_ALIGNED(A, 64);
  DATA_TYPE (* restrict B_)[N_] =
    (DATA_TYPE (*)[N_])ASSUME_ALIGNED(B, 64);
  DATA_TYPE * restrict tmp_ =
    (DATA_TYPE *)ASSUME_ALIGNED(tmp, 64);
  DATA_TYPE * restrict x_ =
    (DATA_TYPE *)ASSUME_ALIGNED(x, 64);
  DATA_TYPE * restrict y_ =
    (DATA_TYPE *)ASSUME_ALIGNED(y, 64);

#pragma scop
  /* Parallelize over rows. Each iteration i:
   *  - reads row i of A and B
   *  - reads the whole x vector
   *  - writes only tmp[i] and y[i]
   * so iterations are independent and can safely run in parallel.
   *
   * If the code is compiled without OpenMP support, this pragma is
   * ignored and execution remains sequential (same as the original).
   */
#pragma omp parallel for schedule(static)
  for (i = 0; i < N_; i++)
    {
      /* Per-row accumulators kept in registers. They represent the
       * same running sums that tmp[i] and y[i] held in the original
       * code, but we avoid repeated loads/stores to memory inside
       * the inner loop.
       */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      DATA_TYPE y_i   = SCALAR_VAL(0.0);

      const DATA_TYPE * restrict Ai = A_[i];
      const DATA_TYPE * restrict Bi = B_[i];

      /* Inner dot products:
       *   tmp_i = sum_j A[i][j] * x[j]
       *   y_i   = sum_j B[i][j] * x[j]
       *
       * #pragma omp simd encourages SIMD vectorization with reductions
       * on tmp_i and y_i. When OpenMP is not enabled, this pragma is
       * ignored by the compiler.
       */
#pragma omp simd reduction(+:tmp_i, y_i)
      for (j = 0; j < N_; j++)
	{
	  DATA_TYPE xj = x_[j];
	  tmp_i += Ai[j] * xj;
	  y_i   += Bi[j] * xj;
	}

      /* Store final results for this row. This matches the original:
       *   tmp[i] = sum_j A[i][j] * x[j];
       *   y[i]   = alpha * tmp[i] + beta * sum_j B[i][j] * x[j];
       */
      tmp_[i] = tmp_i;
      y_[i]   = alpha * tmp_i + beta * y_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
