  DATA_TYPE (*restrict B_r)[n] = B;
  DATA_TYPE *restrict tmp_r    = tmp;
  DATA_TYPE *restrict x_r      = x;
  DATA_TYPE *restrict y_r      = y;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

#pragma scop
  /* Each iteration over i is independent: it reads row i of A and B,
     the full vector x, and writes tmp[i] and y[i] only. This makes
     the loop safely parallelizable. To actually run in parallel,
     compile with -fopenmp; otherwise this pragma is ignored. */
#pragma omp parallel for schedule(static) private(j) if (_PB_N > 128)
  for (i = 0; i < _PB_N; i++)
    {
      /* Row pointers for better locality and fewer address calculations. */
      const DATA_TYPE *restrict Ai = A_r[i];
      const DATA_TYPE *restrict Bi = B_r[i];

      /* Use scalar accumulators held in registers instead of repeatedly
         reading/writing tmp[i] and y[i] in the inner loop. */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      DATA_TYPE y_i   = SCALAR_VAL(0.0);

      /* Compute two dot-products: row i of A and B with x. */
      for (j = 0; j < _PB_N; j++)
	{
	  const DATA_TYPE xj = x_r[j];
	  tmp_i += Ai[j] * xj;
	  y_i   += Bi[j] * xj;
	}

      /* Store results back to memory once per element. */
      tmp_r[i] = tmp_i;
      y_r[i]   = alpha_local * tmp_i + beta_local * y_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

