}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use local (restrict-qualified) pointers to help the compiler
     assume non-aliasing between A, B, x, y, tmp.
   - Accumulate dot products in registers (sumA, sumB) instead of
     repeatedly reading/writing tmp[i] and y[i] inside the inner loop.
     tmp[i] is written once per row, preserving final contents.
   - Preserve row-major access pattern for A and B and sequential
     access for x to maximize cache efficiency and enable vectorization.
   - Optionally exploit thread-level parallelism over the outer i-loop
     with OpenMP (ignored when compiled without OpenMP support).
*/
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

  /* Use the PolyBench loop bound macro as in the original code. */
  const int n_iter = _PB_N;

  /* Create local restrict-qualified aliases.
     This explicitly tells the compiler that these arrays do not alias
     each other, which helps it keep accumulators in registers and
     vectorize the inner loop more aggressively. */
  DATA_TYPE (* restrict A_)[N] = A;
  DATA_TYPE (* restrict B_)[N] = B;
  DATA_TYPE * restrict tmp_    = tmp;
  DATA_TYPE * restrict y_      = y;
  const DATA_TYPE * restrict x_ = x;

#pragma scop
  /* Parallelize across rows if OpenMP is enabled at compile time.
     - Each iteration only touches row i of A and B and element i of
       tmp and y, so iterations are independent. */
#pragma omp parallel for schedule(static)
  for (i = 0; i < n_iter; i++)
    {
      /* Register accumulators for the two dot products:
         sumA = A[i][:] · x[:]
         sumB = B[i][:] · x[:] */
      DATA_TYPE sumA = SCALAR_VAL(0.0);
      DATA_TYPE sumB = SCALAR_VAL(0.0);

      /* Row pointers to improve locality and avoid repeated address
         computation inside the inner loop. */
      const DATA_TYPE * restrict A_row = A_[i];
      const DATA_TYPE * restrict B_row = B_[i];

      for (j = 0; j < n_iter; j++)
	{
	  const DATA_TYPE xj = x_[j];
	  sumA += A_row[j] * xj;
	  sumB += B_row[j] * xj;
	}

      /* Store the final dot product for tmp[i], preserving the value
         that the original code would have produced. */
      tmp_[i] = sumA;

      /* Final linear combination is identical to the original:
         y[i] = alpha * (A[i][:]·x) + beta * (B[i][:]·x) */
      y_[i] = alpha * sumA + beta * sumB;
    }
#pragma endscop

}


